declare(strict_types=1);

/* Production templates for the approved Línea + FISITAAP HTML. */
function r15_icon(string $name):string {
    $p=['trash'=>'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7','menu'=>'M4 6h16M4 12h16M4 18h16','close'=>'m6 6 12 12M18 6 6 18','search'=>'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0','arrow'=>'M5 12h14m-5-5 5 5-5 5','plus'=>'M12 5v14M5 12h14','overview'=>'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z','bag'=>'M5 7h14l2 14H3L5 7zm3 0V5a4 4 0 0 1 8 0v2','orders'=>'M6 3h12v18l-3-2-3 2-3-2-3 2V3zm3 5h6m-6 4h6','users'=>'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 3a4 4 0 0 1 0 8m9 10v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0','box'=>'m3 7 9-5 9 5v10l-9 5-9-5V7zm0 0 9 5 9-5m-9 5v10M7 4.8l10 5.6','wallet'=>'M3 6h17v15H3V6zm0 0V4h15v2m-3 6h6v5h-6z','truck'=>'M1 4h14v13H1zm14 5h4l3 4v4h-7M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0m13 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0','sales'=>'M3 20h18M6 16V9m6 7V4m6 7v-6','full'=>'M3 9V3h6m6 0h6v6M3 15v6h6m6 0h6v-6','chat'=>'M4 3h16v14H9l-5 4V3zm4 5h8m-8 4h5','clock'=>'M12 8v5l3 2M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0','credit'=>'M2 5h20v14H2zM2 10h20M6 15h3','store'=>'M3 9l2-6h14l2 6M4 10v11h16V10M9 21v-8h6v8M3 9h18'];
    return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'.($p[$name]??$p['box']).'"/></svg>';
}
function r15_initial(string $name):string { $parts=preg_split('/\s+/u',trim($name));return mb_strtoupper(mb_substr($parts[0]??'',0,1).mb_substr($parts[1]??'',0,1)); }
function r15_reader_sidebar(App $app,array $u,?array $t):void {
    $driver=$u['role']==='driver';$base=$driver?'driver':'account';$links=$driver?['driver-work'=>'Express disponibles','driver-active'=>'En curso','driver-history'=>'Mis entregas y pagos','driver-affiliations'=>'Mis negocios','driver-profile'=>'Mi perfil']:['customer-orders'=>'Mis pedidos','customer-profile'=>'Mi cuenta','customer-addresses'=>'Mis direcciones','fidelizacion'=>'Fidelización'];
    echo '<aside id="navigation" class="sidebar" data-admin-menu><div class="sidebar-head nav-brand"><a class="brand admin-brand" href="'.e(url($base)).'">'.r15_brand($app,$u,$t).'</a><button class="icon-button" type="button" data-admin-menu-toggle aria-controls="adminMenuLinks" aria-expanded="false" aria-label="Cerrar menú"><span aria-hidden="true">×</span></button></div><nav id="adminMenuLinks" class="sidebar-groups nav-groups"><details class="nav-group" open><summary><span>'.($driver?'Mi trabajo':'Tu cuenta').'</span></summary><div class="nav-group-links">';foreach($links as $id=>$label)echo '<a class="side-link nav-link" href="'.e(url($base).'#'.$id).'">'.e($label).'</a>';echo '</div></details></nav><div class="sidebar-foot nav-foot"><span>'.e($u['name']).'</span><form method="post" action="'.e(url('logout')).'">'.csrf_field().'<button class="side-logout">Cerrar sesión</button></form></div></aside>';
}
function r15_today():string {return ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'][(int)date('w')].', '.date('j').' de '.['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'][(int)date('n')-1];}
function r15_brand(App $app,array $u,?array $t):string {
    $logo=public_media_url($app->setting('platform_logo',url('assets/fisitapp-logo.webp')));
    return '<img class="hybrid-brand" src="'.e($logo).'" alt="FISITAAP">'.($t?'<span class="hybrid-brand-divider"></span><span><strong>'.e($t['name']).'</strong><small>'.e($GLOBALS['r15_branch_name']??'Tu negocio, al día.').'</small></span>':'');
}
function r15_shell_start(App $app,array $u,?array $t,string $title,string $active='dashboard',bool $welcome=false,bool $terminal=false,?array $branch=null):void {
    $GLOBALS['r15_shell']=true;$GLOBALS['r15_terminal']=$terminal;$GLOBALS['r15_tenant']=$t;$GLOBALS['r15_branch_name']=$branch['name']??($t?($app->one('SELECT name FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY is_default DESC,id LIMIT 1',[$t['id']])['name']??''):'');
    $base=match($u['role']){'master'=>'master','driver'=>'driver','customer'=>'account',default=>'admin'};$role=match($u['role']){'master'=>'Administrador','driver'=>'Motorizado','customer'=>'Comprador',default=>restructure_role_name_r1($app,$u)};
    echo '<div id="r15App" class="r15-shell '.($terminal?'r3-terminal':'admin-shell').($welcome?' r15-welcome':'').'">';
    if($terminal)echo '<div class="admin-shell r13-terminal-navigation">';if(in_array($u['role'],['driver','customer'],true))r15_reader_sidebar($app,$u,$t);else admin_sidebar($app,$u,$t,$active);if($terminal)echo '</div>';
    echo '<header class="topbar r15-topbar '.($terminal?'r3-topbar':'').'"><button class="icon-button admin-mobile-launch" type="button" data-admin-menu-toggle aria-expanded="false" aria-controls="adminMenuLinks" aria-label="Abrir menú">'.r15_icon('menu').'</button><a class="brand" href="'.e(url($base)).'">'.r15_brand($app,$u,$t).'</a><button class="header-search r15-search-launch" type="button" data-r15-search aria-label="Buscar en el sistema">'.r15_icon('search').'<span>Buscar en tu espacio…</span><span class="keycap">⌘ K</span></button><nav class="right mode-switch" aria-label="Tu espacio"><a class="active" aria-current="page" href="'.e(url($base)).'">'.r15_icon($u['role']==='master'?'overview':'store').(match($u['role']){'master'=>'Maestro','driver'=>'Moto','customer'=>'Mis pedidos',default=>'Negocio'}).'</a>'.($t?'<a href="'.e(url($t['slug'].'/'.catalog_segment($t))).'" target="_blank">'.r15_icon('bag').'Catálogo</a>':'<a href="'.e(url()).'" target="_blank">'.r15_icon('store').'Web oficial</a>').'</nav><span class="profile-select">'.e($role).'</span><details class="r15-profile"><summary class="avatar" aria-label="Mi cuenta">'.e(r15_initial($u['name'])).'</summary><div><strong>'.e($u['name']).'</strong><small>'.e($role).'</small><a href="'.e(url('ayuda?perfil='.($u['role']==='master'?'master':'store'))).'" target="_blank">Academiaap</a><form method="post" action="'.e(url('logout')).'">'.csrf_field().'<button>Cerrar sesión</button></form></div></details></header>';
    echo '<div class="breadcrumb"><div class="hstack"><a href="'.e(url($base)).'">'.(match($u['role']){'master'=>'Plataforma','driver'=>'Motorizado','customer'=>'Tu cuenta',default=>'Mi espacio'}).'</a><span>/</span><span class="current">'.e($title).'</span></div><span class="r15-live-state" data-r15-live-status></span></div><div class="view-container" id="r15Viewport"><main class="view admin-main '.($terminal?'r3-main':'').'" data-r15-page="'.e($active).'">';
    if(empty($GLOBALS['r15_custom_heading'])){
        $description=$terminal?(str_contains($active,'mesas')?'Tu salón, de un vistazo. Selecciona una mesa para continuar su cuenta.':'La venta fluye. Tú sigues cerca de tus clientes.'):'';
        echo '<div class="page-heading"><div><h1>'.e($title==='Mesas'?'Mesas y caja':$title).'</h1>'.($description?'<p>'.e($description).'</p>':'').'</div><div class="toolbar">'.($terminal?'<span data-r15-incoming></span><button class="icon-button" data-r15-full type="button" aria-label="Pantalla completa">'.r15_icon('full').'</button>':($t?'<a class="btn" target="_blank" href="'.e(url($t['slug'])).'">Ver tienda</a>':'')).'</div></div>';
    }
    unset($GLOBALS['r15_custom_heading']);render_flashes();academy17_shell($app,$u,$t);if($t&&r17_ready($app)&&!in_array($u['role'],['customer','driver'],true)&&module_enabled_v12($app,$t,'personnel'))echo '<div data-hr17-clock data-endpoint="'.e(url('api/personal/marcar')).'" hidden></div>';
}
function r15_shell_end():void {
    global $app;$u=current_user();
    if(empty($GLOBALS['r15_terminal']))echo '<footer class="view-footer"><span><i class="dot"></i> FISITAAP</span><span>'.e(r15_today()).'</span></footer>';
    echo '</main></div></div>';
    if($u&&$u['role']==='customer'&&!empty($GLOBALS['r15_tenant']))fc_chat_ui($app,'cliente',$GLOBALS['r15_tenant'],$u,false);elseif($u&&!in_array($u['role'],['driver','customer'],true)&&function_exists('r2_active')&&r2_active($app))r2_chat_widget($app);
    echo '<dialog class="r15-command" id="r15Command"><header class="dialog-head"><h2>Buscar en tu espacio</h2><button class="icon-button" type="button" data-r15-close aria-label="Cerrar búsqueda">'.r15_icon('close').'</button></header><div class="dialog-body"><input class="input" data-r15-command-input placeholder="Escribe una pantalla o función…" aria-label="Buscar pantalla"><div data-r15-command-results></div></div></dialog>';
    $GLOBALS['r15_shell']=false;layout_end();
}
function r15_product_caption(array $product,array $categories):string {
    $name='';foreach($categories as $c)if((int)$c['id']===(int)$product['category_id']){$name=$c['name'];break;}
    $stock=number_format(max(0,(float)($product['stock']??0)),(int)($product['decimals']??0),',',' ');
    return $name.(!empty($product['track_inventory'])?' · '.$stock.' en existencia':'');
}
function r15_money(float $value):string {
    $decimals=abs($value-round($value))<.000001?0:2;
    return '₡'.number_format($value,$decimals,',',' ');
}
function r15_metric(string $title,string $value,string $trend,string $extra,string $icon='sales'):string {
    return '<article class="card metric"><div class="metric-label">'.e($title).r15_icon($icon).'</div><strong class="metric-value" title="'.e($value).'">'.e($value).'</strong><div class="metric-foot"><strong>'.e($trend).'</strong><span>'.e($extra).'</span></div></article>';
}
function r15_line_chart(array $rows,bool $currency=true):string {
    $format=static fn($n)=>$currency?r15_money((float)$n):number_format((float)$n,0,',',' ');
    $max=max(1,...array_map(static fn($r)=>(float)$r['total'],$rows));$n=count($rows);$points=[];$labels=[];
    foreach($rows as $i=>$r){$x=45+($n>1?$i*474/($n-1):0);$y=148-((float)$r['total']/$max)*115;$points[]=round($x,2).','.round($y,2);if($i===0||$i===$n-1||$i%max(1,(int)ceil($n/7))===0)$labels[]='<text x="'.$x.'" y="177" text-anchor="middle">'.e($r['label']).'</text>';}
    $path='M'.implode(' L',$points);
    return '<div class="chart-wrap"><svg viewBox="0 0 560 190" role="img" aria-label="'.($currency?'Ventas registradas del período':'Negocios creados en el período').'"><g class="chart-grid"><path d="M42 33H535M42 91H535M42 148H535"/></g><g class="chart-axis"><text x="3" y="37">'.e($format($max)).'</text><text x="3" y="95">'.e($format($max/2)).'</text><text x="3" y="152">'.($currency?'₡0':'0').'</text>'.implode('',$labels).'</g><path class="chart-fill" d="'.$path.' L519,148 L45,148 Z"/><path class="chart-line" d="'.$path.'"/>'.implode('',array_map(static fn($p,$r)=>'<circle class="chart-point" cx="'.explode(',',$p)[0].'" cy="'.explode(',',$p)[1].'" r="3"><title>'.e($r['label'].' · '.$format((float)$r['total'])).'</title></circle>',$points,$rows)).'</svg></div>';
}
function r15_sales_chart(App $app,int $tid,?int $branch,string $period):array {
    $scope=$branch?' AND branch_id=?':'';$args=$branch?[$tid,$branch]:[$tid];$days=$period==='month'?29:6;
    if($period==='today'){
        $data=$app->all('SELECT HOUR(created_at) bucket,SUM(total) total FROM sales WHERE tenant_id=?'.$scope.' AND status IN("completed","credit") AND created_at>=CURDATE() AND created_at<DATE_ADD(CURDATE(),INTERVAL 1 DAY) GROUP BY HOUR(created_at)',$args);$map=array_column($data,'total','bucket');$end=max(6,(int)date('G'));$rows=[];for($h=$end-6;$h<=$end;$h++)$rows[]=['label'=>str_pad((string)$h,2,'0',STR_PAD_LEFT).':00','total'=>(float)($map[$h]??0)];return $rows;
    }
    $data=$app->all('SELECT DATE(created_at) bucket,SUM(total) total FROM sales WHERE tenant_id=?'.$scope.' AND status IN("completed","credit") AND created_at>=DATE_SUB(CURDATE(),INTERVAL '.$days.' DAY) AND created_at<DATE_ADD(CURDATE(),INTERVAL 1 DAY) GROUP BY DATE(created_at)',$args);$map=array_column($data,'total','bucket');$rows=[];for($i=$days;$i>=0;$i--){$date=date('Y-m-d',strtotime('-'.$i.' day'));$rows[]=['label'=>date('d/m',strtotime($date)),'total'=>(float)($map[$date]??0)];}return $rows;
}
function r15_owner_dashboard(App $app,array $u,array $t):void {
    if(!role_can($u['role'],'dashboard')){qa180_welcome($app,$u,$t);return;}
    $tid=(int)$t['id'];$branches=$app->all('SELECT id,name FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY is_default DESC,id',[$tid]);$branch=(int)($_GET['branch']??0);if($branch&&!in_array($branch,array_map('intval',array_column($branches,'id')),true))$branch=0;
    $scope=$branch?' AND branch_id=?':'';$args=$branch?[$tid,$branch]:[$tid];$period=in_array($_GET['period']??'today',['today','week','month'],true)?($_GET['period']??'today'):'today';
    $sales=$app->one('SELECT COUNT(*) n,COALESCE(SUM(total),0) total,COALESCE(AVG(total),0) avg_ticket FROM sales WHERE tenant_id=?'.$scope.' AND status IN("completed","credit") AND created_at>=CURDATE() AND created_at<DATE_ADD(CURDATE(),INTERVAL 1 DAY)',$args);
    $counts=$app->one('SELECT COUNT(*) n,SUM(status="new") fresh FROM orders WHERE tenant_id=?'.$scope.' AND status NOT IN("delivered","cancelled")',$args);
    $pending=$app->all('SELECT id,order_number,customer_name,status,total,delivery_type FROM orders WHERE tenant_id=?'.$scope.' AND status NOT IN("delivered","cancelled") ORDER BY created_at DESC LIMIT 3',$args);
    $low=(int)($app->one('SELECT COUNT(*) n FROM product_inventory WHERE tenant_id=?'.$scope.' AND track_stock=1 AND (quantity-reserved_quantity)<=GREATEST(min_stock,reorder_point)',$args)['n']??0);
    $chart=r15_sales_chart($app,$tid,$branch,$period);$name=explode(' ',trim($u['name']))[0];$GLOBALS['r15_custom_heading']=true;admin_shell_start('Resumen',$u,$t,'dashboard');
    echo '<div class="page-heading"><div><p class="eyebrow">'.e(r15_today()).'</p><h1>Todo en orden, '.e($name).'.</h1><p>Esto es lo que está pasando en '.e($t['name']).'.</p></div><div class="toolbar"><form method="get"><input type="hidden" name="period" value="'.e($period).'"><select class="input" name="branch" aria-label="Sucursal del resumen" data-r15-submit><option value="0">Todas las sucursales</option>';foreach($branches as $b)echo '<option value="'.(int)$b['id'].'" '.($branch===(int)$b['id']?'selected':'').'>'.e($b['name']).'</option>';echo '</select></form><a class="btn primary" href="'.e(url('admin/ventas')).'">'.r15_icon('plus').'Nueva venta</a></div></div>';
    echo '<div class="r15-overview-data" data-live-region="overview"><div class="metrics">'.r15_metric('Ventas de hoy',r15_money((float)$sales['total']),'Hoy','ventas registradas','sales').r15_metric('Pedidos activos',str_pad((string)$counts['n'],2,'0',STR_PAD_LEFT),(int)$counts['fresh'].' nuevos','por aceptar','orders').r15_metric('Ticket promedio',r15_money((float)$sales['avg_ticket']),'Hoy','por venta','credit').r15_metric('Clientes atendidos',(string)$sales['n'],'Hoy','transacciones','users').'</div>';
    echo '<div class="dash-grid"><section class="card dash-chart"><header class="card-header"><div><h2>Así se mueve tu negocio</h2><p>Ventas registradas · CRC</p></div><div class="tabs" aria-label="Período del gráfico">';foreach(['today'=>'Hoy','week'=>'Semana','month'=>'Mes'] as $key=>$label)echo '<a class="'.($key===$period?'active':'').'" href="'.e(url('admin?period='.$key.'&branch='.$branch)).'">'.$label.'</a>';echo '</div></header>'.r15_line_chart($chart).'<div class="chart-caption"><span><i class="dot"></i>Ventas completadas</span><a href="'.e(url('admin/reportes')).'">Ver reporte '.r15_icon('arrow').'</a></div></section><section class="card dash-orders"><header class="card-header"><div><h2>Pedidos que necesitan atención</h2><p>'.(int)$counts['n'].' pedidos activos en este momento</p></div><span class="pill">'.(int)$counts['n'].'</span></header><div class="orders-mini">';
    foreach($pending as $o)echo '<article class="order-mini"><span class="avatar">'.e(r15_initial($o['customer_name'])).'</span><a href="'.e(url('admin/pedidos?view='.(int)$o['id'])).'"><strong>'.e($o['customer_name']).'</strong><small>'.e($o['order_number']).' · '.($o['delivery_type']==='pickup'?'Retiro en tienda':'Entrega').'</small></a><div class="amount"><b>'.r15_money((float)$o['total']).'</b><span class="pill">'.e(function_exists('op180_status_label')?op180_status_label($o['status']):ui_label_qa($o['status'])).'</span></div></article>';
    if(!$pending)echo '<div class="empty">Todos los pedidos están al día.</div>';
    echo '</div><footer class="card-footer"><span>Cada pedido, en el momento correcto</span><a href="'.e(url('admin/pedidos')).'">Ver todos '.r15_icon('arrow').'</a></footer></section><section class="card dash-activity"><header class="card-header"><h2>Pequeños detalles, gran diferencia</h2></header><div class="card-body activity-grid">';
    foreach([['box',$low.' productos por revisar','Anticípate al mínimo de inventario.','Ver inventario','inventario'],['wallet','Tu caja, al día','Revisa el estado de tus turnos.','Revisar turno','turnos'],['truck','Entregas en movimiento','Coordina a tu equipo de motorizados.','Ver Express','express-pendientes']] as [$ic,$head,$copy,$link,$route])if(r17_section($app,$t,$route)&&module_enabled_v12($app,$t,section_module_v12($route)))echo '<article class="activity-item">'.r15_icon($ic).'<div><b>'.e($head).'</b><p>'.e($copy).'</p><a href="'.e(url('admin/'.$route)).'">'.e($link).' →</a></div></article>';
    echo '</div></section></div><div class="welcome-strip"><div><b>Más tiempo para lo que hace especial a tu negocio.</b><p>Ventas, pedidos y personas, conectados en un solo espacio.</p></div><button class="btn small" type="button" data-r15-chat>Hablar con FISIChat '.r15_icon('arrow').'</button></div></div>';admin_shell_end();
}
function r15_master_dashboard(App $app,array $u):void {
    $scope="slug NOT IN('tienda-demo','restaurante-demo') AND slug NOT REGEXP '^demo-(restaurante|tienda)-[0-9a-f]{32}$'";
    $tenants=$app->all('SELECT id,name,plan,expires_at,is_active,created_at FROM tenants WHERE '.$scope.' ORDER BY created_at DESC,id DESC');$active=count(array_filter($tenants,static fn($t)=>(bool)$t['is_active']));$current=count(array_filter($tenants,static fn($t)=>$t['is_active']&&(!$t['expires_at']||substr($t['expires_at'],0,10)>=date('Y-m-d'))));
    $contacts=(int)($app->one('SELECT COUNT(*) n FROM contacts WHERE tenant_id IS NULL AND status="new"')['n']??0);$devices=(int)($app->one('SELECT COUNT(*) n FROM fisitaap_r2_devices WHERE is_active=1')['n']??0);
    $rows=[];for($i=6;$i>=0;$i--){$day=date('Y-m-d',strtotime('-'.$i.' day'));$rows[]=['label'=>date('d/m',strtotime($day)),'total'=>count(array_filter($tenants,static fn($t)=>substr($t['created_at'],0,10)===$day))];}
    $GLOBALS['r15_custom_heading']=true;admin_shell_start('Resumen de plataforma',$u,null,'dashboard');echo '<div class="page-heading"><div><p class="eyebrow">ADMINISTRACIÓN FISITAAP</p><h1>Una plataforma, bajo control.</h1><p>Una mirada clara a tus negocios y suscripciones.</p></div><div class="toolbar"><a class="btn primary" href="'.e(url('master/empresas')).'">'.r15_icon('plus').'Agregar negocio</a></div></div><div class="r15-overview-data" data-live-region="overview"><div class="metrics">'.r15_metric('Negocios activos',(string)$active,'Activos','en la plataforma','store').r15_metric('Suscripciones',(string)$current,'Al día','planes vigentes','credit').r15_metric('Contactos nuevos',(string)$contacts,'Pendientes','por atender','chat').r15_metric('Equipos vinculados',(string)$devices,'Activos','en tus negocios','overview').'</div><div class="dash-grid"><section class="card dash-chart"><header class="card-header"><div><h2>Crecimiento de la plataforma</h2><p>Alta de negocios · últimos 7 días</p></div></header>'.r15_line_chart($rows,false).'<div class="chart-caption"><span><i class="dot"></i>Negocios creados</span><a href="'.e(url('master/reportes')).'">Ver reporte '.r15_icon('arrow').'</a></div></section><section class="card dash-orders"><header class="card-header"><div><h2>Negocios en tu plataforma</h2><p>Relaciones que siguen creciendo</p></div><span class="pill">'.count($tenants).'</span></header><div class="orders-mini">';
    foreach(array_slice($tenants,0,3) as $t)echo '<article class="order-mini"><span class="avatar">'.e(r15_initial($t['name'])).'</span><a href="'.e(url('master/empresas?edit='.(int)$t['id'])).'"><strong>'.e($t['name']).'</strong><small>'.e($t['plan']).($t['expires_at']?' · vence '.e(substr($t['expires_at'],0,10)):'').'</small></a><div class="amount"><span class="pill '.($t['is_active']?'green':'').'">'.($t['is_active']?'Activo':'Inactivo').'</span></div></article>';
    echo '</div><footer class="card-footer"><span>Cuentas con atención cercana</span><a href="'.e(url('master/empresas')).'">Ver todos '.r15_icon('arrow').'</a></footer></section><section class="card dash-activity"><header class="card-header"><h2>Lo próximo en tu agenda</h2></header><div class="card-body activity-grid">';
    foreach([['clock','Próximos vencimientos','Revisa los planes y mantén cada cuenta al día.','Revisar suscripciones','planes'],['chat',$contacts.' contactos por atender','Alguien quiere dar su siguiente paso.','Abrir contactos','contactos'],['overview','Tus herramientas','Configura los módulos y equipos de la plataforma.','Ver módulos','modules']] as [$ic,$title,$copy,$label,$route])echo '<article class="activity-item">'.r15_icon($ic).'<div><b>'.e($title).'</b><p>'.e($copy).'</p><a href="'.e(url('master/'.$route)).'">'.e($label).' →</a></div></article>';
    echo '</div></section></div><div class="welcome-strip"><div><b>La información correcta, para decidir mejor.</b><p>Negocios, planes y soporte desde un mismo lugar.</p></div><button class="btn small" type="button" data-r15-chat>Hablar con FISIChat '.r15_icon('arrow').'</button></div></div>';admin_shell_end();
}
